// Errors.
var (
	ErrInvalidDate  = errors.New("invalid date")
	ErrInvalidRange = errors.New("invalid date range")
	ErrInvalidGroup = errors.New("invalid group")
)

// MaxDays is the longest range a report covers.
const MaxDays = 366

// Groups a report can be bucketed by.
const (
	GroupDay   = "day"
	GroupWeek  = "week"
	GroupMonth = "month"
)

// Bucket is what an organization took in one day, week or month: Start is the first day of the bucket (YYYY-MM-DD).
type Bucket struct {
	Start    string                 `json:"start"`
	Amounts  map[money.Currency]int64 `json:"amounts"`
	Payments int                    `json:"payments"`
}

// Report is the revenue report: every bucket from the one holding from to the one holding to, in order.
type Report struct {
	TimeZone string   `json:"time_zone"`
	Group    string   `json:"group"`
	Buckets  []Bucket `json:"buckets"`
}

// paid is one succeeded payment, with the day it belongs to in the organization's time zone.
type paid struct {
	day    time.Time
	cur    money.Currency
	amount int64
}

// parseRange reads from and to (YYYY-MM-DD, both included) and checks them.
func parseRange(from, to string) (time.Time, time.Time, error) {
	start, err := time.Parse(time.DateOnly, from)
	if err != nil {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: from %q", ErrInvalidDate, from)
	}
	last, err := time.Parse(time.DateOnly, to)
	if err != nil {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: to %q", ErrInvalidDate, to)
	}
	if last.Before(start) {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: to is before from", ErrInvalidRange)
	}
	if last.Sub(start) >= MaxDays*24*time.Hour {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: at most %d days", ErrInvalidRange, MaxDays)
	}
	return start, last, nil
}

// successful returns the organization's succeeded payments from the day start to the day last, both included, with
// their days taken in the organization's time zone, and that time zone.
func successful(st *store.Store, orgID string, start, last time.Time) ([]paid, *time.Location, error) {
	org, ok := st.Org(orgID)
	if !ok {
		return nil, nil, store.ErrNotFound
	}
	loc, err := time.LoadLocation(org.TimeZone)
	if err != nil {
		return nil, nil, fmt.Errorf("organization time zone %q: %w", org.TimeZone, err)
	}
	var out []paid
	for _, p := range st.Payments(orgID, "") {
		if p.Status != store.PaymentSucceeded {
			continue
		}
		y, m, d := p.CreatedAt.In(loc).Date()
		day := time.Date(y, m, d, 0, 0, 0, 0, time.UTC)
		if day.Before(start) || day.After(last) {
			continue
		}
		out = append(out, paid{day: day, cur: p.Currency, amount: p.Amount})
	}
	return out, loc, nil
}

// Revenue adds up the organization's succeeded payments per day and currency, from the day from to the day to (YYYY-MM-DD,
// both included). Days are days in the organization's time zone. The result is in date order, currencies in alphabetical
// order within a day; days without payments are left out.
func Revenue(st *store.Store, orgID, from, to string) ([]DayRevenue, error) {
	start, last, err := parseRange(from, to)
	if err != nil {
		return nil, err
	}
	payments, _, err := successful(st, orgID, start, last)
	if err != nil {
		return nil, err
	}
	type key struct {
		day string
		cur money.Currency
	}
	sums := map[key]*DayRevenue{}
	for _, p := range payments {
		k := key{p.day.Format(time.DateOnly), p.cur}
		d, ok := sums[k]
		if !ok {
			d = &DayRevenue{Date: k.day, Currency: k.cur}
			sums[k] = d
		}
		d.Amount += p.amount
		d.Payments++
	}

