// paymentsFixture is an organization in time zone tz with one invoice, and a function that records a payment on it.
func paymentsFixture(t *testing.T, tz string) (*store.Store, string, func(int64, money.Currency, store.PaymentStatus, time.Time)) {
	t.Helper()
	st := store.New()
	utc := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	o, err := st.CreateOrg("A", store.OrgTeam, tz, 0, utc)
	if err != nil {
		t.Fatal(err)
	}
	c, _ := st.CreateCustomer(o.ID, "Jane", "jane@example.com", utc)
	inv, _ := st.CreateInvoice(store.Invoice{OrgID: o.ID, CustomerID: c.ID, Currency: money.USD, Lines: []store.Line{{Description: "x", Quantity: 1, UnitAmount: 1}}}, utc)
	pay := func(amount int64, cur money.Currency, status store.PaymentStatus, at time.Time) {
		if _, err := st.CreatePayment(store.Payment{OrgID: o.ID, InvoiceID: inv.ID, Amount: amount, Currency: cur, Status: status}, at); err != nil {
			t.Fatal(err)
		}
	}
	return st, o.ID, pay
}

// summary lists each bucket as "start payments amounts", for comparing whole reports.
func summary(rep Report) []string {
	var out []string
	for _, b := range rep.Buckets {
		out = append(out, fmt.Sprintf("%s %d %v", b.Start, b.Payments, b.Amounts))
	}
	return out
}

func TestRevenueReportTimeZone(t *testing.T) {
	st, orgID, pay := paymentsFixture(t, "America/New_York")
	ny, err := time.LoadLocation("America/New_York")
	if err != nil {
		t.Fatal(err)
	}
	at := func(m time.Month, d, h, min int) time.Time { return time.Date(2026, m, d, h, min, 0, 0, ny) }
	pay(1000, money.USD, store.PaymentSucceeded, at(3, 2, 22, 30)) // 03-03 in UTC, 03-02 in New York
	pay(500, money.USD, store.PaymentSucceeded, at(3, 2, 9, 0))
	pay(700, money.EUR, store.PaymentSucceeded, at(3, 3, 0, 0))
	pay(999, money.USD, store.PaymentFailed, at(3, 2, 12, 0))
	pay(300, money.USD, store.PaymentSucceeded, at(3, 4, 23, 59))
	pay(100, money.USD, store.PaymentSucceeded, at(3, 5, 0, 0))  // after the range
	pay(50, money.USD, store.PaymentSucceeded, at(2, 28, 23, 0)) // before the range
	rep, err := RevenueReport(st, orgID, "2026-03-01", "2026-03-04", "")
	if err != nil {
		t.Fatal(err)
	}
	want := []string{
		"2026-03-01 0 map[]",
		"2026-03-02 2 map[USD:1500]",
		"2026-03-03 1 map[EUR:700]",
		"2026-03-04 1 map[USD:300]",
	}
	if rep.TimeZone != "America/New_York" || rep.Group != GroupDay || !slices.Equal(summary(rep), want) {
		t.Fatalf("report = %+v\nwant %v", rep, want)
	}
}

func TestRevenueReportDaylightSaving(t *testing.T) {
	// New York springs forward on 2026-03-08 at 02:00, so that day is 23 hours long.
	st, orgID, pay := paymentsFixture(t, "America/New_York")
	ny, err := time.LoadLocation("America/New_York")
	if err != nil {
		t.Fatal(err)
	}
	at := func(m time.Month, d, h, min int) time.Time { return time.Date(2026, m, d, h, min, 0, 0, ny) }
	pay(100, money.USD, store.PaymentSucceeded, at(3, 7, 23, 30)) // EST
	pay(10, money.USD, store.PaymentSucceeded, at(3, 8, 0, 30))   // EST, still 03-08
	pay(20, money.USD, store.PaymentSucceeded, at(3, 8, 23, 59))  // EDT, 03-09 in UTC, still 03-08
	pay(40, money.USD, store.PaymentSucceeded, at(3, 9, 0, 0))    // EDT
	rep, err := RevenueReport(st, orgID, "2026-03-07", "2026-03-09", GroupDay)
	if err != nil {
		t.Fatal(err)
	}
	want := []string{
		"2026-03-07 1 map[USD:100]",
		"2026-03-08 2 map[USD:30]",
		"2026-03-09 1 map[USD:40]",
	}
	if !slices.Equal(summary(rep), want) {
		t.Fatalf("report = %+v\nwant %v", rep, want)
	}
}

func TestRevenueReportGroups(t *testing.T) {
